"""Write docs/data_inventory.md from the personal-data registry (BETA_10 §2; CHK-SEC-1).

python scripts/data_inventory.py
"""

from __future__ import annotations

from pathlib import Path

from reflexo.common import personal_data

OUT = Path(__file__).resolve().parent.parent / "docs" / "data_inventory.md"


def render_markdown() -> str:
    lines = [
        "# Data inventory",
        "",
        "Generated by `scripts/data_inventory.py` from `config/personal_data.yaml` (BETA_10 §2; CHK-SEC-1).",
        "Do not edit by hand: tag the column in the registry and regenerate.",
        "",
        "| Category | Columns | Purpose | Role | Retention |",
        "|---|---|---|---|---|",
    ]
    for c in personal_data.inventory():
        cols = "; ".join(f"`{t}`: {', '.join(cs)}" for t, cs in c.columns.items())
        lines.append(f"| {c.name} | {cols} | {c.purpose} | {c.role} | {c.retention} |")
    lines += ["", "## Reviewed and not personal", "", "| Column | Why |", "|---|---|"]
    lines += [f"| `{t}.{col}` | {why} |" for (t, col), why in sorted(personal_data.not_personal().items())]
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    OUT.write_text(render_markdown(), encoding="utf-8")
    print(f"wrote {OUT}")
